from typing import Literal, Union

import pydantic

from ...schemas.rapi.base import BaseRapiResponseSchema


class PollsAnswerSchema(pydantic.BaseModel):
    answerId: str
    votes: int


class PollsStopResponseSchema(BaseRapiResponseSchema): ...


class PollsGetResultsSchema(pydantic.BaseModel):
    type: Literal["anon", "public"]
    closed: bool
    answers: list[PollsAnswerSchema]
    voters: dict
    myAnswerId: str
    canStop: bool


class PollsGetResponseSchema(BaseRapiResponseSchema):
    results: PollsGetResultsSchema


class PollsStopSchema(BaseRapiResponseSchema): ...


class PollsRevokeResponseSchema(BaseRapiResponseSchema): ...


class PollsVoteResultsSchema(pydantic.BaseModel):
    answers: list[PollsAnswerSchema]


class PollsVoteResponseSchema(BaseRapiResponseSchema):
    results: PollsVoteResultsSchema


class PollsSubscribeResponseSchema(BaseRapiResponseSchema): ...


class PollsRespondersResultsSchema(pydantic.BaseModel):
    users: list[str]
    newest: Union[str, int]
    oldest: Union[str, int]
    exhausted: bool


class PollsRespondersResponseSchema(BaseRapiResponseSchema):
    results: PollsRespondersResultsSchema
